#include <iostream>
#include <fstream>
#include <string>
#include <sstream>

using namespace std;

int main() {
    string filename;
    string wordToFind;

    // Get the filename from the user
    cout << "Enter the filename: ";
    cin >> filename;

    // Get the word to search for
    cout << "Enter the word to find: ";
    cin >> wordToFind;

    ifstream inputFile(filename);

    // Check if the file opened successfully
    if (!inputFile.is_open()) {
        cerr << "Error opening file: " << filename << endl;
        return 1; // Indicate an error
    }

    int wordCount = 0;
    string line;

    // Read the file line by line
    while (getline(inputFile, line)) {
        // Use stringstream to easily split the line into words
        stringstream ss(line);
        string word;

        // Extract words from the line
        while (ss >> word) {
            // Convert both the word and the word to find to lowercase for case-insensitive comparison
            string lowerWord = "";
            for (char c : word) {
                lowerWord += tolower(c);
            }
            string lowerWordToFind = "";
            for (char c : wordToFind) {
                lowerWordToFind += tolower(c);
            }

            // Check if the current word matches the word to find
            if (lowerWord == lowerWordToFind) {
                wordCount++;
            }
        }
    }

    // Close the file
    inputFile.close();

    // Print the result
    cout << "The word \"" << wordToFind << "\" appears " << wordCount << " times in the file." << endl;

    return 0; // Indicate successful execution
}
```

